          ]
        },
        {
          "proposicao": "A fonte referencia documentos de planejamento de inspeção por RBI, gestão da integridade de amarração e extensão de vida de unidades flutuantes, indicando que essas metodologias podem compor o arcabouço técnico de integridade de instalações offshore.",
          "trechos": [
            "E8112ae5b2cabd595:1392:2090"
          ],
