          ]
        },
        {
          "proposicao": "A fonte recomenda avaliar tanques de FPSO de casco simples que tenham ou tiveram armazenamento de água produzida, incluindo análise de integridade e da funcionalidade do sistema de proteção catódica e do revestimento.",
          "trechos": [
            "Eea56a8c8b09d16b8:694:1391"
